function generate(){state.betMode='combined';state.ticket=optimizeCombo(visibleMatches().filter(match=>!match.completed),Number($('#target-odds').value),Number($('#selection-count').value),$('#risk-profile').value);renderTicket();const total=state.ticket.reduce((p,x)=>p*x.odd,1);toast(`Combiné ${$('#risk-profile').selectedOptions[0].text.toLowerCase()} : cote ${total.toFixed(2)} avec ${state.ticket.length} matchs`)}
