$('#share-combo').addEventListener('click',async()=>{if(!state.ticket.length)return;const total=state.ticket.reduce((product,item)=>product*item.odd,1),independent=state.betMode!=='combined',type=state.betMode==='single'?'Paris simples':state.betMode==='multiple'?'Paris multiples':`Combiné ${$('#risk-profile').selectedOptions[0].text}`,summary=independent?`${state.ticket.length} paris indépendants`:`Cote totale : ${total.toFixed(2)}`,text=`BetMaster · ${type}\n${state.ticket.map((item,index)=>`${index+1}. ${item.match}\n   ${item.label} @ ${item.odd.toFixed(2)}`).join('\n')}\n${summary}\nSimulation uniquement · 18+ · Jouez responsablement.`;try{if(navigator.share)await navigator.share({title:`Mon ticket BetMaster · ${type}`,text});else await navigator.clipboard.writeText(text);toast(navigator.share?'Ticket partagé':'Ticket copié dans le presse-papiers')}catch(error){if(error?.name!=='AbortError')toast('Impossible de partager ce ticket')}});
$('#place-bet').addEventListener('click',()=>{if(!accountAuthenticated){$('#account-dialog').showModal();toast('Connectez-vous ou créez un compte pour enregistrer ce pari');return}const stake=Number($('#stake').value),single=state.betMode==='single',multiple=state.betMode==='multiple',totalStake=stake*(single?state.ticket.length:1);if(!state.ticket.length||stake<=0||totalStake>state.bankroll)return;const date=new Date().toISOString();state.bankroll-=totalStake;if(single)state.history.unshift(...state.ticket.map(item=>({date,items:[item],stake,odds:item.odd,status:'pending',betType:'single'})));else if(multiple){const formula=$('#system-formula').value,lines=systemLines(state.ticket,formula);if(!lines.length)return;const systemBets=lines.map(line=>({...line,stake:stake/lines.length}));state.history.unshift({date,items:[...state.ticket],stake,odds:systemBets.reduce((sum,line)=>sum+line.odds,0)/systemBets.length,status:'pending',betType:'multiple',systemFormula:formula,systemLines:systemBets})}else{const odds=state.ticket.reduce((p,x)=>p*x.odd,1);state.history.unshift({date,items:[...state.ticket],stake,odds,status:'pending',betType:'combined'})}const count=state.ticket.length;state.ticket=[];persist();render();setActiveTab('bankroll',true);toast(single?`${count} paris simples ajoutés à votre historique`:multiple?'Pari système ajouté à votre historique':'Combiné ajouté à votre historique')});
$('#open-add-match').addEventListener('click',()=>{const dialog=$('#match-dialog');dialog.querySelector('[name=date]').value=isoDate(0);dialog.showModal()});$('#match-form').addEventListener('submit',e=>{if(e.submitter?.value==='cancel')return;const d=Object.fromEntries(new FormData(e.target));state.customMatches.push({id:`custom-${Date.now()}`,date:d.date,priority:50,league:d.league,time:d.time,home:d.home,away:d.away,homeGoals:Number(d.homeGoals),awayGoals:Number(d.awayGoals),odds:{home:Number(d.oddHome),draw:Number(d.oddDraw),away:Number(d.oddAway),over:1.85,btts:1.80}});persist();render();toast('Match analysé et ajouté')});
$('#edit-bankroll').addEventListener('click',()=>$('#bankroll-dialog').showModal());$('#bankroll-form').addEventListener('submit',e=>{if(e.submitter?.value==='cancel')return;const amount=Number(new FormData(e.target).get('amount'));if(!Number.isFinite(amount)||amount<=0)return;state.bankroll+=amount;state.capitalEvents.unshift({date:new Date().toISOString(),amount});persist();render();toast(`${money(amount)} ajoutés à votre bankroll`)});
$('#profile-form').addEventListener('submit',e=>{e.preventDefault();if(!e.target.reportValidity())return;const data=new FormData(e.target);state.profile={nickname:String(data.get('nickname')).trim().slice(0,24)||'Parieur',avatar:String(data.get('avatar')),face:String(data.get('face')),accessory:String(data.get('accessory'))};persist();renderCommunity();$('#account-label').textContent=state.profile.nickname;$('#profile-dialog').close();toast('Profil et avatar enregistrés')});
$('#profile-form').addEventListener('input',e=>{const form=e.currentTarget,data=new FormData(form);applyAvatar($('#profile-avatar-preview'),{avatar:String(data.get('avatar')),face:String(data.get('face')),accessory:String(data.get('accessory'))})});
$('#community-profile-button').addEventListener('click',()=>{if(!accountAuthenticated){$('#account-dialog').showModal();toast('Créez un compte pour définir votre profil');return}renderCommunity();$('#profile-dialog').showModal()});
$('#open-account-settings').addEventListener('click',()=>{$('#profile-dialog').close();$('#account-dialog').showModal()});
