$('#prediction-filters').addEventListener('change',()=>{state.predictionFilters={period:$('#prediction-period').value,league:$('#prediction-league').value,market:$('#prediction-market').value,result:$('#prediction-result').value};state.predictionPage=1;renderPredictionStats()});
$('#reset-prediction-filters').addEventListener('click',()=>{state.predictionFilters={period:'all',league:'all',market:'all',result:'all'};state.predictionPage=1;renderPredictionStats()});
$('#prediction-prev').addEventListener('click',()=>{if(state.predictionPage>1){state.predictionPage--;renderPredictionStats();$('#predictions').scrollIntoView({behavior:'smooth'})}});$('#prediction-next').addEventListener('click',()=>{state.predictionPage++;renderPredictionStats();$('#predictions').scrollIntoView({behavior:'smooth'})});
$('#challenge-list').addEventListener('click',e=>{const button=e.target.closest('[data-join-challenge]');if(!button)return;if(!accountAuthenticated){$('#account-dialog').showModal();toast('Connectez-vous pour participer à un challenge');return}const id=button.dataset.joinChallenge,joined=challengeEntry(id);state.challengeEntries=joined?state.challengeEntries.filter(item=>(typeof item==='string'?item:item.id)!==id):[...state.challengeEntries,{id,joinedAt:new Date().toISOString()}];persist();renderCommunity();toast(challengeEntry(id)?'Challenge rejoint':'Participation annulée')});
const syncThemeColor=()=>{const meta=document.querySelector('meta[name=theme-color]');if(meta)meta.content=document.documentElement.classList.contains('light')?'#F2F4F0':'#0A0C0B'};
$('#theme-toggle').addEventListener('click',()=>{document.documentElement.classList.toggle('light');localStorage.setItem('betmaster-theme',document.documentElement.classList.contains('light')?'light':'dark');syncThemeColor();render()});if(localStorage.getItem('betmaster-theme')!=='dark')document.documentElement.classList.add('light');syncThemeColor();
