document.querySelectorAll('[data-footer-nav]').forEach(button=>button.addEventListener('click',()=>{const target=button.dataset.footerNav;setActiveTab(['bankroll','standings','community','predictions'].includes(target)?target:'matches');document.querySelector(target==='bankroll'?'#bankroll':target==='standings'?'#standings':target==='community'?'#community':target==='predictions'?'#predictions':target==='builder'?'#builder':'#matches')?.scrollIntoView({behavior:'smooth'})}));
