try{const cached=JSON.parse(localStorage.getItem(FIXTURES_CACHE_KEY)||'null');if(cached)applyFixtureData(cached,true)}catch{}setActiveTab(location.hash==='#bankroll'?'bankroll':location.hash==='#classements'?'standings':['#communaute','#challenges'].includes(location.hash)?'community':location.hash==='#bilan-pronos'?'predictions':'matches');render();if(typeof window!=='undefined'){$('#footer-year').textContent=new Date().getFullYear();history.scrollRestoration='manual';if(!['#bankroll','#communaute','#challenges','#bilan-pronos'].includes(location.hash))scrollTo({top:0,behavior:'instant'});$('#match-list').classList.add('reveal');setInterval(tickCountdowns,1000);setInterval(pollLive,20000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)pollLive()});addEventListener('pageshow',pollLive);addEventListener('online',pollLive);setupScroller($('#date-navigator'));setupScroller($('#filters'));setupScroller($('#standings-leagues'));import('./details.js?v=fiches-7').then(module=>{details=module.initDetails({allMatches,logoTag,leagueLogoUrl,LEAGUES,isLive,kickoffAt,state,toast,updateScrollers});if(location.hash==='#classements')details.showStandings()}).catch(error=>console.error('Fiches indisponibles',error));addEventListener('resize',updateScrollers);requestAnimationFrame(()=>{revealActive($('#date-navigator'),false);updateScrollers()});setTimeout(pollLive,1500);setTimeout(()=>document.documentElement.classList.remove('intro'),2000);loadLiveFixtures();setInterval(loadLiveFixtures,5*60*1000);setInterval(updateFreshness,60000);import('./account.js?v=accounts-v5').then(({initAccountSync})=>initAccountSync({getState:userStatePayload,applyState:applySyncedState,resetState:resetSyncedState,registerCloudSave:save=>{cloudSave=save},onAuthChange:authenticated=>{accountAuthenticated=authenticated;renderTicket()},onCommunityData:profiles=>{state.communityProfiles=profiles;renderCommunity()},toast})).catch(error=>{console.error('Compte indisponible',error);$('#account-label').textContent='Compte indisponible'})}
